-- =====================================================================
-- Repair, 2026-10: text pasted into Supabase through `pbcopy` without a
-- UTF-8 locale arrived as Mac Roman (each UTF-8 byte became one character).
-- Generated by scripts/repair/make-mojibake-repair.py. This file is pure
-- ASCII on purpose (non-ASCII as U&'' escapes), so it survives any clipboard.
--
--   1. Re-creates the functions whose bodies held non-ASCII text, from the
--      migrations: the same definitions; CREATE OR REPLACE keeps grants.
--   2. Rewrites stored text the corrupted code wrote: credential labels
--      (the provisioning function's default label), and the test owner's
--      rows if they still exist.
--
-- Safe to re-run: each UPDATE matches only the corrupted value. The last
-- query should print four "true".
-- =====================================================================
begin;

-- app.operator_provision_owner, as in migrations/013_owner_invoice_code.sql
create or replace function app.operator_provision_owner(
  p_actor_user_id uuid,
  p_credential_id uuid,
  p_name          text,
  p_contact_phone text,
  p_device_no     text,
  p_location      text,
  p_invoice_code  text
) returns table (out_status text, out_owner_id uuid, out_machine_id uuid)
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_owner   uuid := gen_random_uuid();
  v_machine uuid := gen_random_uuid();
  v_name    text := btrim(coalesce(p_name, ''));
  v_device  text := btrim(coalesce(p_device_no, ''));
  v_code    text := btrim(coalesce(p_invoice_code, ''));
  v_phone   text := app.norm_phone(p_contact_phone);
begin
  if not app.is_operator_user(p_actor_user_id) then
    return query select 'forbidden'::text, null::uuid, null::uuid;
    return;
  end if;
  if p_credential_id is null or length(v_name) < 2 or length(v_name) > 120 then
    return query select 'invalid_name'::text, null::uuid, null::uuid;
    return;
  end if;
  -- A Mongolian mobile: 976 + 8 digits. Anything else is a typo, and a typo
  -- here is the phone a future invite will be checked against.
  if v_phone is null or v_phone !~ '^976[0-9]{8}$' then
    return query select 'invalid_phone'::text, null::uuid, null::uuid;
    return;
  end if;
  if v_device !~ '^[A-Za-z0-9_-]{3,40}$' then
    return query select 'invalid_device'::text, null::uuid, null::uuid;
    return;
  end if;
  -- Optional now: QPay gives the code to the OWNER with their username and
  -- password, and the owner may type all three. Checked only when given.
  if v_code <> '' and v_code !~ '^[A-Za-z0-9_-]{3,64}$' then
    return query select 'invalid_invoice_code'::text, null::uuid, null::uuid;
    return;
  end if;
  if exists (select 1 from public.machines m where m.device_no = v_device) then
    return query select 'device_taken'::text, null::uuid, null::uuid;
    return;
  end if;

  insert into public.owners (id, name, contact_phone, status)
  values (v_owner, v_name, v_phone, 'active');

  -- 'pending' with no sealed blob: the shape 003's state-machine CHECK
  -- requires. is_active must be false - the same CHECK derives it.
  insert into public.qpay_credentials
    (id, owner_id, label, status, is_active, source, pending_invoice_code, invoice_code_hint)
  values
    (p_credential_id, v_owner, U&'\04AE\043D\0434\0441\044D\043D \0434\0430\043D\0441', 'pending', false, 'cli',
     nullif(v_code, ''), nullif(right(v_code, 4), ''));

  -- notify_url stays NULL until the machine's first signed getQrCode pins it.
  insert into public.machines
    (id, owner_id, qpay_credential_id, device_no, label, location, notify_url, status, installed_at)
  values
    (v_machine, v_owner, p_credential_id, v_device, null, nullif(btrim(coalesce(p_location, '')), ''),
     null, 'active', now());

  insert into public.credential_audit (owner_id, credential_id, action, actor_kind, actor_user_id, detail)
  values (v_owner, p_credential_id, 'owner_provisioned', 'operator', p_actor_user_id,
          jsonb_build_object('device_no', v_device, 'invoice_code_hint', nullif(right(v_code, 4), '')));

  return query select 'ok'::text, v_owner, v_machine;
exception
  -- Two operators registering the same machine at once: the unique
  -- constraint decides, and the loser is told plainly.
  when unique_violation then
    return query select 'device_taken'::text, null::uuid, null::uuid;
end $$;

-- app.operator_problems, as in migrations/007_operator_console.sql
create or replace function app.operator_problems(
  p_actor_user_id uuid,
  p_limit         integer default 50,
  p_now           timestamptz default now()
) returns table (
  kind text, at timestamptz, device_no text, owner_name text,
  amount_mnt integer, detail text, reference text
)
language sql stable security definer set search_path = '' as $$
  with guard as (select app.is_operator_user(p_actor_user_id) as ok)
  -- Money confirmed, sale never completed. The worst kind: the customer paid.
  select 'needs_human'::text, r.created_at, r.device_no, o.name, r.amount_mnt,
         coalesce(r.last_error, 'settle attempts exhausted'), r.order_no
    from public.orders r join public.owners o on o.id = r.owner_id, guard g
   where g.ok and r.status = 'needs_human'
  union all
  -- Paid, machine told, no cup reported.
  select 'paid_no_cup', r.notified_at, r.device_no, o.name, r.amount_mnt,
         U&'\043C\04E9\043D\0433\04E9 \0430\0432\0441\0430\043D, \043A\043E\0444\0435 \0433\0430\0440\0430\0430\0433\04AF\0439', r.order_no
    from public.orders r join public.owners o on o.id = r.owner_id, guard g
   where g.ok and r.status = 'paid' and r.product_done_ok is distinct from true
     and r.notified_at > p_now - interval '30 days'
     and r.notified_at < p_now - interval '5 minutes'
  union all
  -- A machine tried to sell and we refused, or could not place it.
  select 'ingest_error', e.at, e.device_no, null, null, e.reason, e.order_no
    from public.ingest_errors e, guard g
   where g.ok and e.at > p_now - interval '7 days'
  union all
  -- A login code that never arrived.
  select 'sms_failed', s.at, null, null, null,
         coalesce(s.error, 'gateway refused'), s.phone
    from public.sms_sends s, guard g
   where g.ok and not s.ok and s.at > p_now - interval '7 days'
  union all
  -- A merchant account that has started refusing us.
  select 'credential_failing', c.updated_at, null, o.name, null,
         coalesce(c.last_error_code, 'auth failing') || ' (' || c.auth_fail_count || ')', c.username_hint
    from public.qpay_credentials c join public.owners o on o.id = c.owner_id, guard g
   where g.ok and c.auth_fail_count > 0
  order by 2 desc
  limit p_limit;
$$;

-- app.owner_problems, as in migrations/015_machine_faults.sql
create or replace function app.owner_problems(
  p_owner_id uuid,
  p_limit    integer default 100,
  p_now      timestamptz default now()
) returns table (
  kind text, at timestamptz, device_no text, amount_mnt integer, detail text, reference text
)
language sql stable security definer set search_path = '' as $$
  select 'needs_human'::text, r.created_at, r.device_no, r.amount_mnt,
         null::text, r.order_no
    from public.orders r
   where r.owner_id = p_owner_id and r.status = 'needs_human'
  union all
  select 'paid_no_cup', r.notified_at, r.device_no, r.amount_mnt, r.product_name, r.order_no
    from public.orders r
   where r.owner_id = p_owner_id and r.status = 'paid' and r.product_done_ok is distinct from true
     and r.notified_at > p_now - interval '30 days'
     and r.notified_at < p_now - interval '5 minutes'
  union all
  select 'order_failed', r.created_at, r.device_no, r.amount_mnt, r.product_name, r.order_no
    from public.orders r
   where r.owner_id = p_owner_id and r.status = 'failed'
     and r.created_at > p_now - interval '7 days'
  union all
  select 'machine_refused', e.at, e.device_no, null, e.reason, e.order_no
    from public.ingest_errors e
    join public.machines m on m.device_no = e.device_no and m.owner_id = p_owner_id
   where e.at > p_now - interval '7 days'
  union all
  select 'qpay_failing', c.updated_at, null, null, c.last_error_code, c.username_hint
    from public.qpay_credentials c
   where c.owner_id = p_owner_id and c.auth_fail_count > 0
  union all
  select 'machine_silent', max(r.created_at), m.device_no, null, null, null
    from public.machines m
    join public.orders r on r.machine_id = m.id
   where m.owner_id = p_owner_id and m.status = 'active'
   group by m.device_no
  having max(r.created_at) < p_now - interval '24 hours'
  union all
  -- The machine's own fault, as Jetinno's SaaS reported it.
  select 'machine_fault', f.occurred_at, f.device_no, null,
         nullif(concat_ws(U&' \00B7 ', nullif(f.code, ''), f.description), ''), f.status_text
    from public.machine_faults f
    join public.machines m on m.device_no = f.device_no and m.owner_id = p_owner_id
   where f.resolved_at is null and f.occurred_at > p_now - interval '7 days'
  order by 2 desc
  limit least(greatest(coalesce(p_limit, 100), 1), 500);
$$;

-- app.accept_owner_invite, as in migrations/003_owner_self_service.sql
create or replace function app.accept_owner_invite(
  p_token     text,
  p_user_id   uuid,
  p_source_ip inet default null
) returns table (out_status text, out_owner_id uuid, out_owner_name text, out_role text)
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_inv    public.owner_invites;
  v_name   text;
  v_phone  text;
  v_ok     timestamptz;
begin
  if p_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_token is null or length(p_token) < 20 then
    return query select 'invalid'::text, null::uuid, null::text, null::text;
    return;
  end if;

  select * into v_inv
    from public.owner_invites i
   where i.token_hash = sha256(convert_to(p_token, 'utf8'))
   for update;

  if not found then
    return query select 'invalid'::text, null::uuid, null::text, null::text;
    return;
  end if;

  -- Record the presentation BEFORE deciding anything, so a mismatch is durable.
  update public.owner_invites i
     set attempt_count   = i.attempt_count + 1,
         last_attempt_at = now(),
         last_attempt_ip = p_source_ip
   where i.id = v_inv.id;

  if v_inv.revoked_at is not null then
    return query select 'revoked'::text, null::uuid, null::text, null::text;
    return;
  end if;

  if v_inv.accepted_at is not null then
    if v_inv.accepted_by = p_user_id then
      select o.name into v_name from public.owners o where o.id = v_inv.owner_id;
      return query select 'already_accepted'::text, v_inv.owner_id, v_name, v_inv.role;
    else
      return query select 'used'::text, null::uuid, null::text, null::text;
    end if;
    return;
  end if;

  if v_inv.expires_at <= now() then
    return query select 'expired'::text, null::uuid, null::text, null::text;
    return;
  end if;

  select u.phone, u.phone_confirmed_at into v_phone, v_ok
    from auth.users u where u.id = p_user_id;

  if v_ok is null
     or app.norm_phone(v_phone) is null
     or app.norm_phone(v_phone) is distinct from app.norm_phone(v_inv.invited_phone) then
    insert into public.credential_audit
      (owner_id, action, actor_user_id, actor_kind, source_ip, detail)
    values
      (v_inv.owner_id, 'invite_mismatch', p_user_id, 'owner', p_source_ip,
       jsonb_build_object('invite_reference', v_inv.reference,
                          'attempt', v_inv.attempt_count + 1));
    return query select 'phone_mismatch'::text, null::uuid, null::text, null::text;
    return;
  end if;

  -- Single use, atomically: the same shape as the settle lease in section 2.
  update public.owner_invites i
     set accepted_at = now(), accepted_by = p_user_id, accepted_ip = p_source_ip
   where i.id = v_inv.id and i.accepted_at is null;
  if not found then
    return query select 'used'::text, null::uuid, null::text, null::text;
    return;
  end if;

  -- ON CONFLICT names the CONSTRAINT, not the columns. An inference list of
  -- bare column names inside a function with same-named OUT parameters raises
  -- "column reference is ambiguous" AT RUNTIME - a failure that appears only
  -- on the happy path, i.e. on the first real owner who signs up. The OUT
  -- parameters here are all out_-prefixed for the same reason; keep it that way.
  insert into public.owner_members (owner_id, user_id, role)
  values (v_inv.owner_id, p_user_id, v_inv.role)
  on conflict on constraint owner_members_pkey do nothing;

  select o.name into v_name from public.owners o where o.id = v_inv.owner_id;

  insert into public.credential_audit
    (owner_id, action, actor_user_id, actor_kind, source_ip, detail)
  values
    (v_inv.owner_id, 'member_joined', p_user_id, 'owner', p_source_ip,
     jsonb_build_object('invite_reference', v_inv.reference, 'role', v_inv.role));

  return query select 'accepted'::text, v_inv.owner_id, v_name, v_inv.role;
end $$;

-- app.credential_verify_budget, as in migrations/003_owner_self_service.sql
create or replace function app.credential_verify_budget(
  p_owner_id    uuid,
  p_username_fp text,
  p_per_hour    integer default 5,
  p_per_day     integer default 20,
  p_distinct    integer default 2,
  p_lock_fails  integer default 5,
  p_lock_min    integer default 60
) returns table (out_allowed boolean, out_reason text, out_retry_minutes integer)
language plpgsql stable security definer set search_path = '' as $$
declare
  v_hour      integer;
  v_day       integer;
  v_distinct  integer;
  v_streak    integer;
  v_last_fail timestamptz;
begin
  select count(*) into v_hour from public.credential_verify_attempts a
   where a.owner_id = p_owner_id and a.at > now() - interval '1 hour'
     and a.outcome <> 'qpay_unreachable';
  select count(*) into v_day from public.credential_verify_attempts a
   where a.owner_id = p_owner_id and a.at > now() - interval '24 hours'
     and a.outcome <> 'qpay_unreachable';
  select count(distinct a.username_fp) into v_distinct
    from public.credential_verify_attempts a
   where a.owner_id = p_owner_id and a.at > now() - interval '24 hours'
     and a.outcome <> 'qpay_unreachable';

  -- Consecutive auth failures since the last non-auth-failure outcome.
  select count(*), max(a.at) into v_streak, v_last_fail
    from public.credential_verify_attempts a
   where a.owner_id = p_owner_id
     and a.outcome = 'auth_failed'
     and a.at > coalesce((select max(b.at) from public.credential_verify_attempts b
                           where b.owner_id = p_owner_id
                             and b.outcome not in ('auth_failed','qpay_unreachable')),
                         'epoch'::timestamptz);

  if v_streak >= p_lock_fails and v_last_fail > now() - make_interval(mins => p_lock_min) then
    -- Not permanent. A permanent lockout is itself a denial of service on an
    -- owner who fat-fingered, and its recovery path is a phone call to the
    -- operator - the model this whole feature exists to replace.
    return query select false, 'LOCKED'::text,
      ceil(extract(epoch from (v_last_fail + make_interval(mins => p_lock_min) - now())) / 60)::integer;
    return;
  end if;

  if v_hour >= p_per_hour then
    return query select false, 'RATE_LIMITED'::text, 60; return;
  end if;
  if v_day >= p_per_day then
    return query select false, 'RATE_LIMITED'::text, 240; return;
  end if;
  -- The anti-stuffing control. Stuffing needs breadth, not depth: an attacker
  -- with one owner session wants to test other people's usernames, not five
  -- more passwords for the one they already hold. An owner has one or two QPay
  -- merchants, ever.
  if v_distinct >= p_distinct
     and not exists (select 1 from public.credential_verify_attempts a
                      where a.owner_id = p_owner_id and a.at > now() - interval '24 hours'
                        and a.username_fp = p_username_fp) then
    return query select false, 'TOO_MANY_MERCHANTS'::text, 1440; return;
  end if;

  return query select true, null::text, null::integer;
end $$;

-- app.operator_owners, as in migrations/007_operator_console.sql
create or replace function app.operator_owners(
  p_actor_user_id uuid,
  p_tz            text default 'Asia/Ulaanbaatar',
  p_now           timestamptz default now()
) returns table (
  owner_id uuid, owner_name text, contact_phone text, owner_status text,
  machines int, active_machines int,
  month_amount bigint, month_cups int, total_amount bigint,
  last_sale_at timestamptz,
  credential_status text, credential_active boolean, credential_fail_count int,
  has_member boolean, stage text
)
language sql stable security definer set search_path = '' as $$
  -- Each aggregate is its own scalar subquery rather than one grouped join.
  -- Joining machines AND orders AND credentials in a single GROUP BY
  -- multiplies every order row by the number of machines the owner has, and
  -- the owner's revenue silently doubles the day they buy a second machine -
  -- which is exactly the customer you least want to hand a wrong number.
  with bounds as (select date_trunc('month', (p_now at time zone p_tz))::date as month_start)
  select o.id, o.name, o.contact_phone, o.status,
         (select count(*)::int from public.machines m where m.owner_id = o.id),
         (select count(*)::int from public.machines m
           where m.owner_id = o.id and m.status = 'active'),
         (select coalesce(sum(r.amount_mnt),0)::bigint from public.orders r, bounds b
           where r.owner_id = o.id and r.status = 'paid'
             and (r.notified_at at time zone p_tz)::date >= b.month_start),
         (select count(*)::int from public.orders r, bounds b
           where r.owner_id = o.id and r.status = 'paid'
             and (r.notified_at at time zone p_tz)::date >= b.month_start),
         (select coalesce(sum(r.amount_mnt),0)::bigint from public.orders r
           where r.owner_id = o.id and r.status = 'paid'),
         (select max(r.notified_at) from public.orders r
           where r.owner_id = o.id and r.status = 'paid'),
         c.status, c.is_active, c.auth_fail_count::int,
         exists (select 1 from public.owner_members mm where mm.owner_id = o.id),
         case
           when c.status = 'pending'
             and not exists (select 1 from public.owner_members mm where mm.owner_id = o.id) then 'invited'
           when c.status = 'pending' then 'account_created'
           when not exists (select 1 from public.orders r
                             where r.owner_id = o.id and r.status = 'paid') then 'credentials_verified'
           else 'earning'
         end
    from public.owners o
    -- The owner's live credential, or their most recent one. An owner has one
    -- or two in practice; picking here keeps the row count at one per owner.
    left join lateral (
      select qc.status, qc.is_active, qc.auth_fail_count
        from public.qpay_credentials qc
       where qc.owner_id = o.id
       order by qc.is_active desc, qc.updated_at desc
       limit 1
    ) c on true
   where app.is_operator_user(p_actor_user_id)
   order by 7 desc, o.name;
$$;

-- app.claim_invites_by_phone, as in migrations/012_claim_invites.sql
create or replace function app.claim_invites_by_phone(
  p_user_id   uuid,
  p_source_ip inet default null
) returns table (out_owner_id uuid, out_owner_name text, out_role text)
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_phone text;
  v_ok    timestamptz;
  r       record;
begin
  select app.norm_phone(u.phone), u.phone_confirmed_at into v_phone, v_ok
    from auth.users u where u.id = p_user_id;
  if v_phone is null or v_ok is null then return; end if;

  for r in
    select i.id, i.owner_id, i.role, i.reference
      from public.owner_invites i
     where i.invited_phone = v_phone
       and i.accepted_at is null
       and i.revoked_at is null
       and i.expires_at > now()
     order by i.created_at
     for update
  loop
    update public.owner_invites i
       set accepted_at = now(), accepted_by = p_user_id, accepted_ip = p_source_ip,
           attempt_count = i.attempt_count + 1, last_attempt_at = now(), last_attempt_ip = p_source_ip
     where i.id = r.id and i.accepted_at is null;
    if not found then continue; end if;

    -- ON CONFLICT names the constraint - see 003's accept_owner_invite for
    -- why bare column names blow up inside a function with OUT parameters.
    insert into public.owner_members (owner_id, user_id, role)
    values (r.owner_id, p_user_id, r.role)
    on conflict on constraint owner_members_pkey do nothing;

    insert into public.credential_audit
      (owner_id, action, actor_user_id, actor_kind, source_ip, detail)
    values
      (r.owner_id, 'member_joined', p_user_id, 'owner', p_source_ip,
       jsonb_build_object('invite_reference', r.reference, 'role', r.role, 'via', 'phone_match'));

    return query select r.owner_id, o.name, r.role from public.owners o where o.id = r.owner_id;
  end loop;
end $$;

